        _lang() {
            try {
                var l = (window.vcI18n && window.vcI18n._lang) || (window.mySimulation && (window.mySimulation.language || window.mySimulation.currentLanguage)) || document.documentElement.lang || 'es';
                return (String(l).slice(0, 2) === 'en') ? 'en' : 'es';
            } catch (e) { return 'es'; }
        }

        _gradeLabel(perf) {
            var map = { "Banco en Riesgo": "Bank at Risk", "Líder Digital de Arvelia": "Digital Leader of Arvelia", "Transformador Sólido": "Solid Transformer", "En Transición": "In Transition" };
            if (this._lang() === 'es') return perf;
            return map[perf] || perf;
        }

        _num(v, dec) {
            var n = (typeof v === 'number' && isFinite(v)) ? v.toFixed(dec) : String(v);
            return (this._lang() === 'es') ? n.replace('.', ',') : n;
        }

        _tf(key, vars) {
            var self = this;
            var str = window.mySimulation.t(key);
            return String(str).replace(/\{(\w+)\}/g, function (m, k) { return (vars && vars[k] != null) ? String(vars[k]) : m; });
        }

        _insightText(item) {
            var self = this, v = {};
            Object.keys(item.v || {}).forEach(function (k) {
                var x = item.v[k];
                v[k] = (typeof x === 'number') ? self._num(x, (Math.round(x) === x) ? 0 : 1) : x;
            });
            return this._tf(item.k, v);
        }

        formatCompletionMessage(summary) {
            var self = this;
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var verdict = this._gradeLabel(s.performance || '');
            var items = (Array.isArray(s.insightItems) ? s.insightItems : []).map(function (it) {
                return '<li>' + self._insightText(it) + '</li>';
            }).join('');
            var qs = ['cm_q1', 'cm_q2'].map(function (k) { return '<li>' + self._tf(k) + '</li>'; }).join('');
            var md = function (val, lab) {
                return '<div class="bv-cm-metric"><span class="bv-cm-mv">' + val + '</span><span class="bv-cm-ml">' + lab + '</span></div>';
            };
            var pct = function (x) { return (typeof x === 'number') ? self._num(x, 1) + '%' : '-'; };
            var metrics = md(pct(s.finalMarketShareNum), this._tf('cm_ms'))
                + md(pct(s.finalDigitalPenetrationNum), this._tf('cm_dp'))
                + md(pct(s.finalRoENum), this._tf('cm_roe'))
                + md(pct(s.finalCostToIncomeNum), this._tf('cm_ci'))
                + md(((typeof s.totalScore === 'number') ? s.totalScore : 0) + ' / 300', this._tf('cm_total'));
            var tp = s.turningPoint ? '<div class="bv-cm-debrief-title">' + this._tf('cm_turning') + '</div><p class="bv-cm-turning">' + this._insightText(s.turningPoint) + '</p>' : '';
            return '<div class="bv-cm">'
                + '<div class="bv-cm-head">'
                +   '<div class="bv-cm-score">' + score + '<span class="bv-cm-score-max">/100</span></div>'
                +   '<div class="bv-cm-verdict">' + verdict + '</div>'
                + '</div>'
                + '<div class="bv-cm-metrics">' + metrics + '</div>'
                + tp
                + '<div class="bv-cm-debrief-title">' + this._tf('cm_debrief') + '</div>'
                + '<ul class="bv-cm-insights">' + items + '</ul>'
                + '<div class="bv-cm-debrief-title">' + this._tf('cm_questions') + '</div>'
                + '<ul class="bv-cm-insights">' + qs + '</ul>'
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = 0;
            var scores = [];
            history.forEach(function(r) { var v = (r.results && r.results.periodScore) ? r.results.periodScore : 0; scores.push(v); total += v; });
            var last = history[history.length - 1];
            var lr = last.results || {};
            var finalMs  = (typeof lr.marketShare === 'number')        ? lr.marketShare        : 17;
            var finalDp  = (typeof lr.digitalPenetration === 'number') ? lr.digitalPenetration : 34;
            var finalRoe = (typeof lr.roe === 'number')                ? lr.roe                : 11;
            var finalCi  = (typeof lr.costToIncome === 'number')       ? lr.costToIncome       : 68;
            var log = Array.isArray(lr.decisionLog) ? lr.decisionLog.filter(Boolean) : [];
            var n = Math.max(1, log.length);
            var sum = function (f) { return log.reduce(function (a, x) { return a + (+x[f] || 0); }, 0); };
            var fined = !!lr.regulatoryFined;
            var apiAct = (typeof lr.apiAtActivation === 'number') ? lr.apiAtActivation : null;

            // Bands re-derived from the v1.4.0 sweep (P6 and random-player distributions).
            var performance = 'Banco en Riesgo';
            if (total >= 150) performance = 'Líder Digital de Arvelia';
            else if (total >= 120) performance = 'Transformador Sólido';
            else if (total >= 90) performance = 'En Transición';

            // Insights built from this run only (never describe a play the student did not make).
            var items = [];
            if (apiAct !== null) {
                if (fined) items.push({ k: 'ins_fined', v: { api: apiAct } });
                else items.push({ k: 'ins_compliant', v: { api: apiAct } });
            }
            if (sum('core') / n >= 45) items.push({ k: 'ins_debt', v: { core: Math.round(sum('core') / n), ret: lr.techDebtRetired || 0 } });
            if (sum('mobile') / n >= 40) items.push({ k: 'ins_ceiling', v: { ms: finalMs, ci: finalCi, roe: finalRoe } });
            if (log.length && sum('closures') === 0 && sum('hires') === 0) items.push({ k: 'ins_workforce_zero', v: { ci: finalCi } });
            if (log.some(function (x) { return (+x.hires || 0) >= 4; })) items.push({ k: 'ins_overhire', v: {} });
            if (log[0] && log[0].partner) items.push({ k: 'ins_partner_' + log[0].partner, v: {} });
            items.push({ k: 'ins_ci', v: { ci: finalCi, roe: finalRoe } });

            // Turning point: the regulatory check if it was failed; otherwise the round that moved the score most.
            var turningPoint = null;
            if (fined) {
                turningPoint = { k: 'tp_fined', v: { api: apiAct } };
            } else if (scores.length > 1) {
                var best = 1, gain = -1e9;
                for (var i = 1; i < scores.length; i++) { if (scores[i] - scores[i - 1] > gain) { gain = scores[i] - scores[i - 1]; best = i; } }
                turningPoint = { k: 'tp_gain', v: { r: best + 1, a: scores[best - 1], b: scores[best] } };
            }
            var self = this;
            return {
                totalScore:              total,
                overallScore:            Math.max(0, Math.min(100, Math.round(total / Math.max(1, history.length)))),
                finalMarketShare:        finalMs + '%',
                finalDigitalPenetration: finalDp + '%',
                finalRoE:                finalRoe + '%',
                finalMarketShareNum:     finalMs,
                finalDigitalPenetrationNum: finalDp,
                finalRoENum:             finalRoe,
                finalCostToIncomeNum:    finalCi,
                performance:             performance,
                performanceLabel:        this._gradeLabel(performance),
                insightItems:            items,
                turningPoint:            turningPoint,
                insights:                items.map(function (it) { return self._insightText(it); })
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            if (ds.apiReady < 30 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_api_risk');
            }
            if (ds.costToIncome > 65) {
                return window.mySimulation.t('hint_high_costs');
            }
            if (ds.digitalPenetration < 45 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_low_digital');
            }
            return null;
        }

