        _updateBriefing(state) {
            var period = Math.min((state.currentPeriod || 1), this.ROUNDS.length);
            var round  = this.ROUNDS[period - 1];
            if (!round) return;
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = window.mySimulation.t(round.titleKey);
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = window.mySimulation.t(round.descKey);
        }

        _updatePartnershipOptions(state) {
            var period = Math.min((state.currentPeriod || 1), this.ROUNDS.length);
            var round  = this.ROUNDS[period - 1];
            if (!round) return;
            var container = document.getElementById('partnershipOptions');
            if (!container) return;
            container.innerHTML = '';
            round.partnerOptions.forEach(function(opt, idx) {
                var div   = document.createElement('div');
                div.className = 'bv-radio-option';
                var input = document.createElement('input');
                input.type  = 'radio';
                input.name  = 'partnershipChoice';
                input.id    = 'partner_' + opt.id;
                input.value = opt.id;
                input.className = 'bv-partner-radio';
                if (idx === 0) input.checked = true;
                var label = document.createElement('label');
                label.htmlFor   = 'partner_' + opt.id;
                label.textContent = window.mySimulation.t(opt.labelKey);
                div.appendChild(input);
                div.appendChild(label);
                container.appendChild(div);
            });
        }

        _updateProductOptions(state) {
            var period = Math.min((state.currentPeriod || 1), this.ROUNDS.length);
            var round  = this.ROUNDS[period - 1];
            if (!round) return;
            var select = document.getElementById('productSelect');
            if (!select) return;
            select.innerHTML = '';
            round.productOptions.forEach(function(opt) {
                var option = document.createElement('option');
                option.value       = opt.id;
                option.textContent = window.mySimulation.t(opt.labelKey);
                select.appendChild(option);
            });
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new BancaVerdeAdapter(), {
            simulationType:   'bancaverde_fintech_002',
            maxPeriods:       3,
            autoSaveInterval: 30000
        });
    });

})();
